SELECT COUNT(*) FROM users as u, comments as c, postLinks as pl, votes as v, badges as b, posts as p WHERE c.UserId = u.Id AND p.Id = c.PostId AND b.UserId = u.Id AND p.Id = pl.RelatedPostId AND p.Id = v.PostId AND c.CreationDate>='2010-08-01 19:11:47'::timestamp AND c.CreationDate<='2014-09-11 13:42:51'::timestamp AND pl.LinkTypeId=1 AND v.VoteTypeId=2 AND v.CreationDate<='2014-09-10 00:00:00'::timestamp AND b.Date<='2014-08-02 12:24:29'::timestamp;